using System;using System.IO;using System.Text;using System.Linq;using System.Threading;using System.Windows.Forms;
namespace KeyJaya {public static class PreferenceTests {
 static int passed,failed;static void Check(bool ok,string name){if(ok)passed++;else{failed++;Console.WriteLine("FAIL "+name);}}static void Equal(string expected,string actual,string name){Check(expected==actual,name+" expected="+expected+" actual="+actual);}
 [STAThread]public static int Main(string[] args){string folder=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[0])),"preference-test-artifacts",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string path=Path.Combine(folder,"preferences.tsv");
  for(int session=1;session<=3;session++){using(Core c=new Core(args[0],path)){Equal("rāja",c.Convert("rāja","unicode"),"original preferred before completed session "+session);for(int n=0;n<20;n++)Check(c.RememberSpelling("rāja",n%2==0?"räja":"räjä","balaram","auto"),"passing variant staged "+session+" "+n);Equal("rāja",c.Convert("rāja","unicode"),"passing through does not immediately learn "+session);c.FinishSpellingChoice();Equal(session==3?"rājā":"rāja",c.Convert("rāja","unicode"),"three separate final choices threshold "+session);c.FinishSpellingChoice();Equal(session==3?"rājā":"rāja",c.Convert("rāja","unicode"),"empty flush cannot cast vote "+session);}}
  using(Core c=new Core(args[0],path)){Equal("rājā",c.Convert("rāja","unicode"),"preferred persists across restart");Equal("räjä",c.Convert("rāja","balaram"),"preference shared with Balaram");Equal("rAjA",c.Convert("rāja","itrans"),"preference shared with ITRANS");Equal("rājā",c.ClipboardChoices("rāja","unicode","auto")[0],"preferred first cycling option");Check(!c.RememberSpelling("an","ān","unicode","auto"),"English never learns");Check(!c.RememberSpelling("age","āge","unicode","auto"),"English age never learns");Equal("an age since",c.Convert("an age since","unicode"),"English after learning");Check(!c.RememberSpelling("rāja","malicious","unicode","auto"),"unknown spelling rejected");}
  string resetPath=Path.Combine(folder,"reset.tsv");using(Core c=new Core(args[0],resetPath)){c.RememberSpelling("rāja","räjä","balaram","auto");c.FinishSpellingChoice();c.RememberSpelling("rāja","räja","balaram","auto");c.FinishSpellingChoice();for(int i=0;i<2;i++){c.RememberSpelling("rāja","räjä","balaram","auto");c.FinishSpellingChoice();Equal("rāja",c.Convert("rāja","unicode"),"different final choice resets count "+i);}c.RememberSpelling("rāja","räjä","balaram","auto");c.FinishSpellingChoice();Equal("rājā",c.Convert("rāja","unicode"),"three consistent choices after reset");}
  string cancelPath=Path.Combine(folder,"cancel.tsv");using(Core c=new Core(args[0],cancelPath)){for(int i=0;i<5;i++){c.RememberSpelling("rāja","räjä","balaram","auto");c.CancelSpellingChoice();c.FinishSpellingChoice();}Equal("rāja",c.Convert("rāja","unicode"),"undo cancels preference vote");Check(!File.Exists(cancelPath),"cancelled choices never create preference file");}
  string crossPath=Path.Combine(folder,"cross.tsv");for(int i=0;i<3;i++)using(Core c=new Core(args[0],crossPath)){Check(c.RememberSpelling("rāja",i==0?"rājā":i==1?"räjä":"rAjA",i==0?"unicode":i==1?"balaram":"itrans","auto"),"votes across output encodings "+i);}using(Core c=new Core(args[0],crossPath))Equal("rājā",c.Convert("rāja","unicode"),"shutdown flush and cross-encoding learning");
  string timerPath=Path.Combine(folder,"timer.tsv");using(Core c=new Core(args[0],timerPath)){c.RememberSpelling("rāja","räjä","balaram","auto");Thread.Sleep(10300);Check(File.Exists(timerPath),"one-shot inactivity timer saves vote");Equal("rāja",c.Convert("rāja","unicode"),"one inactivity vote never promotes");}
  DataObject payload=Resident.PastePayload("rāja");Equal("rāja",(string)payload.GetData(DataFormats.UnicodeText,false),"temporary clipboard Unicode payload");foreach(string format in new[]{"ExcludeClipboardContentFromMonitorProcessing","CanIncludeInClipboardHistory","CanUploadToCloudClipboard"}){Check(payload.GetDataPresent(format,false),"history exclusion format "+format);MemoryStream stream=payload.GetData(format,false) as MemoryStream;Check(stream!=null&&stream.ToArray().SequenceEqual(new byte[4]),"serialized DWORD zero "+format);}
  Console.WriteLine("PASS: "+passed+" FAIL: "+failed);return failed==0?0:1;
 }
}}
